function Counter() {
  const [count, setCount] = useState(0);

  function addThree() {
    setCount(count + 1); // queue: replace with 0 + 1
    setCount(count + 1); // queue: replace with 0 + 1
    setCount(count + 1); // queue: replace with 0 + 1
    console.log(count);  // 0, the snapshot
  } // next render: count === 1

  function reallyAddThree() {
    setCount((c) => c + 1); // queue: updater
    setCount((c) => c + 1);
    setCount((c) => c + 1);
  } // next render: count === 3

  return <button onClick={reallyAddThree}>{count}</button>;
}
